<form method="POST" action="{{ route('donations.bank.store') }}" enctype="multipart/form-data">@csrf<input type="hidden" name="type" value="{{ $type }}"><input type="hidden" name="target_id" value="{{ $target->id }}">
<div class="section-title">اختر مبلغ التبرع</div><div class="amount-grid">@foreach([10,20,50,100] as $preset)<button type="button" class="amount-btn" data-amount="{{ $preset }}">{{ $preset }}</button>@endforeach</div>
<label for="amount">المبلغ المحوّل (د.ل)</label><input id="amount" type="text" name="amount" inputmode="decimal" lang="en-US" dir="ltr" class="sz-western-digits" pattern="[0-9]+([.][0-9]{1,2})?" title="أدخل مبلغًا صحيحًا مثل 10 أو 25.50" autocomplete="off" required value="{{ old('amount', 10) }}">
<div class="section-title">بيانات التحويل المصرفي</div><label for="account">اختر الحساب المصرفي</label><select name="bank_account_id" id="account" required>@foreach($accounts as $account)<option value="{{ $account->id }}" data-bank="{{ $account->bank_name }}" data-holder="{{ $account->account_holder }}" data-number="{{ $account->account_number }}" data-iban="{{ $account->iban ?? '' }}" @selected(old('bank_account_id')==$account->id)>{{ $account->bank_name }} — {{ $account->account_holder }}</option>@endforeach</select>
<div class="bank-card"><div class="bank-line"><span>اسم المصرف</span><b id="bank-name"></b></div><div class="bank-line"><span>اسم صاحب الحساب</span><b id="bank-holder"></b></div><div class="bank-line"><span>رقم الحساب</span><div><strong id="bank-number"></strong> <button type="button" class="copy" data-copy="bank-number">نسخ</button></div></div><div class="bank-line" id="iban-row"><span>IBAN</span><div><strong id="bank-iban"></strong> <button type="button" class="copy" data-copy="bank-iban">نسخ</button></div></div></div>
<div class="section-title">معلومات الحوالة وإثبات الدفع</div><label for="name">اسم المتبرع</label><input id="name" name="donor_name" required maxlength="150" value="{{ old('donor_name') }}" autocomplete="name"><label for="phone">رقم الهاتف (اختياري)</label><input id="phone" name="donor_phone" maxlength="40" value="{{ old('donor_phone') }}" autocomplete="tel"><label for="reference">رقم الحوالة المصرفية</label><input id="reference" name="transfer_reference" required maxlength="100" value="{{ old('transfer_reference') }}" placeholder="أدخل رقم العملية الموجود على الإيصال"><label for="receipt">صورة الإيصال أو PDF</label><div class="upload"><span>ارفع إثبات التحويل (JPG أو PNG أو PDF)</span><input id="receipt" type="file" name="receipt" accept="image/jpeg,image/png,application/pdf" required><div class="muted">الحد الأقصى 5 ميجابايت</div></div><div class="sz-trust">🔒 بياناتك وإيصالك لا يظهران للزوار، ويُراجع الطلب من الإدارة فقط.</div><button class="submit" type="submit">إرسال الحوالة للمراجعة</button><p class="muted">إرسال الطلب لا يعني تأكيد استلام الأموال. الإدارة تتحقق من وصولها أولًا.</p></form>@endif</main></aside></div>
<script>if(new URLSearchParams(location.search).get('embedded')==='1'){document.body.classList.add('sz-embedded');const close=document.querySelector('.close');if(close){close.addEventListener('click',function(e){if(window.parent!==window){e.preventDefault();window.parent.postMessage({type:'sirte-close-payment'},window.location.origin)}})}}document.addEventListener('DOMContentLoaded',function(){const amount=document.getElementById('amount');const presets=document.querySelectorAll('[data-amount]');function latinDigits(v){return String(v).replace(/[\u0660-\u0669\u06F0-\u06F9]/g,c=>String(c.charCodeAt(0)-(c.charCodeAt(0)<=0x0669?0x0660:0x06F0))).replace(/\u066B/g,'.').replace(/\u066C/g,'')}function sync(){amount.value=latinDigits(amount.value);presets.forEach(b=>b.classList.toggle('selected',b.dataset.amount===amount.value))}if(amount){presets.forEach(b=>b.addEventListener('click',()=>{amount.value=b.dataset.amount;sync()}));amount.addEventListener('input',sync);amount.addEventListener('change',sync);amount.form.addEventListener('submit',()=>{amount.value=latinDigits(amount.value).trim()});sync()}const sel=document.getElementById('account');function showBank(){if(!sel)return;const o=sel.selectedOptions[0];if(!o)return;for(const [key,id] of [['bank','bank-name'],['holder','bank-holder'],['number','bank-number'],['iban','bank-iban']])document.getElementById(id).textContent=o.dataset[key]||'—';document.getElementById('iban-row').hidden=!o.dataset.iban}if(sel){sel.addEventListener('change',showBank);showBank()}document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{const val=document.getElementById(b.dataset.copy).textContent;try{await navigator.clipboard.writeText(val);b.textContent='تم النسخ';setTimeout(()=>b.textContent='نسخ',1800)}catch(e){b.textContent='حدد الرقم لنسخه'}}))});</script></body></html>